const order = orders.get(orderID);
// The order can be COMPLETED while the capture itself is PENDING or DECLINED,
// so only the capture status decides whether money actually arrived.
const capture = jsonResponse.purchase_units?.[0]?.payments?.captures?.[0];
if (order && capture?.status === "COMPLETED") {
  order.status = "paid";
  order.captureId = capture.id;
} else if (order && capture?.status === "PENDING") {
  // Funds not credited yet; wait for PAYMENT.CAPTURE.COMPLETED.
  order.status = "pending";
  order.captureId = capture.id;
}
// DECLINED / FAILED (or no capture at all): leave the order unpaid.
